examples.template:
HStack {
    Toggle({{items.0.label}}, isOn: $isBold)
        .toggleStyle(.monarchButton())
    Toggle({{items.1.label}}, isOn: $showsArchived)
        .toggleStyle(.monarchButton(.outline))
    Toggle(isOn: $isFiltering) {
        Label({{items.2.label}}, systemImage: "line.3.horizontal.decrease")
    }
    .toggleStyle(.monarchButton(.outline))
}

examples.setupTemplate:
@State private var isBold = true
@State private var showsArchived = false
@State private var isFiltering = false

examples.setup:
